INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'Citizenship', 'Unit 3', 'Molarum Grade 10 — Citizenship Unit 3: Understanding Good Governance', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 3: Understanding Good Governance.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('754862a7-9f9a-49b3-8c95-dd55bd166603'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'The act of presenting ideas, words, or other intellectual property of other persons as one’s own is termed as:', 'Plagiarism', 'The excerpt defines presenting others'' intellectual property as one’s own specifically as plagiarism.', 0),('96d6d067-7e3c-4430-8bd5-2e1f6f214b96'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which of the following is listed in the excerpt as NOT an importance of social media for the young citizen?', 'To facilitate conditions to be socially isolated', 'The excerpt explicitly lists facilitating conditions to be socially isolated as the choice that is not an importance of social media for young citizens.', 1),('31f8b479-b112-4d5c-828c-913dbb004ffb'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'The appropriate and responsible use of the internet, computers and digital devices is termed as:', 'Digital competence', 'The excerpt uses the term ''Digital competence'' to refer to appropriate and responsible use of internet and digital devices.', 2),('71c0d6c0-fc7c-4f7a-8b89-0608c63241bc'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'The change of human identities from real life to artificial or imaginary life is referred to as:', 'Secondhand living', 'The multiple-choice item in the excerpt uses the term ''Secondhand living'' to describe change of identities from real to artificial or imaginary life.', 3),('3a72b8d3-fd5b-4298-8856-d67491c25893'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which option best matches the excerpt definition of good governance?', 'All processes of governing and the institutions, processes and practices through which common concerns are decided upon and regulated', 'The excerpt defines good governance as the processes of governing and the institutions and practices through which common concerns are decided and regulated.', 4),('6d88c8d6-745e-4928-8ca3-178744076d05'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'According to the excerpt, good governance is also a way of measuring:', 'How public institutions conduct public affairs and manage public resources effectively', 'The excerpt states good governance measures how public institutions conduct public affairs and manage resources, ensuring efficiency, reliable judiciary and accountability.', 5),('ee3156c8-76ae-4333-8a3e-d62589415b59'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element of good governance ''requires elected and appointed government officials to be answerable for the decisions and acts they undertake'' as described in the excerpt?', 'Accountability', 'The excerpt defines accountability as the principle requiring officials to be answerable for their decisions and acts.', 6),('71ae2590-d2f1-49df-897b-60481bebcb7a'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element refers to the involvement of citizens in the process of decision making?', 'Participation', 'The excerpt explains participation as citizens'' involvement in decision making and expressing concerns without fear or discrimination.', 7),('c0592a95-179a-467f-8396-4b26111219a4'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element requires legal frameworks to be fair and enforced impartially, meaning everyone must obey the law?', 'Rule of law', 'The excerpt states rule of law requires fair legal frameworks enforced impartially, with everyone held accountable under the law.', 8),('18d30bc8-5030-4f8f-873f-ed1ebb545a1a'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element is defined as the availability of information to the general public and clarity about government rules, regulations and decisions?', 'Transparency', 'The excerpt defines transparency as information being freely available, known and directly accessible to those affected by decisions, reducing uncertainty and curbing corruption.', 9),('79bb0514-5018-4e5f-8523-429f69ccb9f9'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element of good governance ensures all members feel they have a stake and are not excluded from society?', 'Equity and Inclusiveness', 'The excerpt explains equity and inclusiveness as ensuring all groups, especially the vulnerable, have opportunities and do not feel excluded from mainstream society.', 10),('7a8dbf09-025a-4f1c-8d56-a08016496be2'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element requires that institutions and processes try to serve all stakeholders within a reasonable time frame?', 'Responsiveness', 'The excerpt states responsiveness means institutions serve stakeholders in a reasonable time frame, gaining legitimacy and wider acceptance.', 11),('4c0ae404-d257-4ef3-81eb-ba59f94eb451'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element of good governance is described as mediating differing interests to reach broader consensus on the best interests of society?', 'Consensus Oriented', 'The excerpt describes consensus oriented governance as mediating differing interests to reach broader societal consensus on policies and procedures.', 12),('c538d018-bd6b-45b9-8af1-f4d365f0f0b4'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which element means processes and institutions produce results that meet society''s needs while making the best use of available resources?', 'Effectiveness and efficiency', 'The excerpt explains effectiveness and efficiency as producing results that meet societal needs while making best use of resources, including sustainable resource use.', 13),('1833c6fd-7f64-4a58-8a6c-1c4b561ddf86'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which of the following is NOT presented as a role of good governance in the excerpt?', 'Promoting absolute rule by a single leader', 'The excerpt lists roles like promoting economic development, peace and social justice and emphasizes participation and rule of law, not absolute rule by a single leader.', 14),('9a614990-5fb9-4196-8e50-0a13eca2064e'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which role of good governance, as described, helps protect property rights and supports equitable enforcement of law to promote inclusive growth?', 'Promoting economic development', 'The excerpt states that promoting economic development via rule of law, efficiency and equitable enforcement supports inclusive growth and protection of property rights.', 15),('48e74624-5dba-4c3d-834a-b3d07584ab3a'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which of the following is cited as an impact of lack of good governance that results in inefficiency in service provisions and may lead to corruption?', 'Inefficient service delivery', 'The excerpt notes lack of good governance causes inefficiency in service delivery and can lead to corruption, for example in health and education sectors.', 16),('51414ee0-4512-4008-8026-811b821d9b1b'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'How does the excerpt define corruption?', 'Misuse of public office or power for one’s own private gain', 'The excerpt defines corruption as misuse of public office or power for private gain and a failure of integrity and moral principles.', 17),('d1180cc1-b09d-4aa7-8c62-9effffd1ff1e'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which of the following is a form of corruption listed in the excerpt involving theft or misappropriation of public resources?', 'Embezzlement', 'The excerpt lists embezzlement as the theft or misappropriation of public resources by public officials.', 18),('f8f0c334-3971-44e6-831d-1e9a3f035239'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'multiple_choice', 'Which way of fighting corruption involves educating and making the public aware of the risks and damaging consequences through media, campaigns, and workshops?', 'Creating public awareness', 'The excerpt identifies creating public awareness through media, campaigns and training as a key mechanism to fight corruption.', 19),('0d74b5aa-4d9d-4ae3-8236-9ae0ee72a260'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'true_false', 'Digital technology has always positive impacts on the socio-economic development of countries.', 'False', 'The excerpt presents a statement asking students to mark this as false, indicating digital technology does not always have positive impacts.', 20),('66d645e3-32d3-4a55-8665-613de7f6a7ba'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'true_false', 'The use of digital technology may lead people to uncontrolled and unmanageable emotions.', 'True', 'The excerpt includes this statement and indicates it is correct, that digital technology may lead to uncontrolled emotions.', 21),('f5f2c3f0-9f55-4638-8222-d90e2647e169'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'true_false', 'Digital technology has the power to change the nature of human interactions.', 'True', 'The excerpt poses this statement as correct, affirming that digital technology can change human interactions.', 22),('512d37b8-9eca-4093-81eb-838aaba6cfbc'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'true_false', 'People with higher social media use are more likely to feel socially isolated than those who do not use social media often.', 'True', 'The excerpt includes this statement and marks it as correct, linking higher social media use with greater likelihood of social isolation.', 23),('8d3ff61a-8450-4c91-8f81-aeaca1cca2f3'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'In one sentence, define good governance as given in the excerpt.', 'Good governance is the processes, institutions and practices through which common concerns are decided upon and regulated and by which public institutions conduct affairs and manage resources efficiently and accountably.', 'This answer combines the excerpt’s definitions that good governance refers to governing processes and how public institutions conduct affairs and manage resources efficiently and accountably.', 24),('7a0b9a50-645f-4d2c-8184-3383f40e5316'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'Name two elements of good governance mentioned in the excerpt.', 'Accountability and Transparency', 'Both accountability and transparency are explicitly listed as elements of good governance in the excerpt.', 25),('4323b2a0-750d-4ee2-8324-3db3cdc44274'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'Explain accountability in the context of good governance in one sentence.', 'Accountability requires elected and appointed officials to be answerable for their decisions and acts and to act according to the will and wishes of the people.', 'The excerpt defines accountability as officials being answerable for decisions and acting according to people’s will, with public awareness of government actions.', 26),('13d55c6e-4d22-40d7-8852-3ad41b6072b2'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'What does transparency mean in the context of government decision making, according to the excerpt?', 'Transparency means information is freely available, known and directly accessible to those affected, with clarity about government rules, decisions and their enforcement.', 'The excerpt explains transparency as openness of information and clarity about government decisions so affected people can access and understand them.', 27),('fbf7fd46-739a-48d0-8a6e-5b2bbb82c3e0'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'How does good governance improve social development as described in the excerpt?', 'Good governance improves social development by ensuring better living conditions, access to health and education, higher incomes and meaningful participation in public affairs.', 'The excerpt links good governance to social development through better living conditions, health and education services, income opportunities and public participation.', 28),('c73b887a-7418-4d2e-8f48-5256977fe0f3'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'Give two ways the media can help fight corruption according to the excerpt.', 'The media can raise public awareness about causes and remedies of corruption and detect, investigate and expose incidents of corruption.', 'The excerpt states media raises awareness and can detect, investigate and expose corruption, informing the public and enabling accountability.', 29),('78fcc16d-d8cc-426d-8ee1-45e1dfdb4daf'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'According to the excerpt, what is corruption?', 'Corruption is the misuse of public office or power for one’s own private gain and an impairment of integrity and moral principles.', 'The excerpt defines corruption as misuse of public office for private benefit and an ethical failure that erodes trust and hampers development.', 30),('32ee6f80-77ae-4912-8e10-562a1eaf4142'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'Name one effect of corruption on the economy mentioned in the excerpt.', 'Corruption distorts economic systems by creating consistent budget deficits which lead to persistent inflation and reduced purchasing power.', 'The excerpt explains corruption distorts the economy, creating budget deficits and persistent inflation that reduce consumers'' real purchasing power.', 31),('14021f76-02d4-453a-8763-d97d8afaa3c6'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'How many lessons are listed under ''Lessons'' for Unit 3 in the excerpt?', '6', 'The excerpt lists six lessons under ''Lessons'' for Unit 3: the concept, elements, role, challenges, impacts, and understanding fighting corruption.', 32),('062ecaf9-8e26-4a1f-83e8-d65c6c09de97'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'According to the ''Elements of good governance'' section, how many elements are commonly practiced by institutions and organizations?', '8', 'The excerpt lists eight commonly practiced elements: accountability, participation, rule of law, transparency, equity and inclusiveness, responsiveness, consensus oriented, and effectiveness and efficiency.', 33),('3999c2bb-c186-4432-89c4-159ee5dc983e'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'How many explicit roles of good governance are described in the ''The role of good governance'' lesson?', '7', 'The excerpt describes seven roles: promoting economic development, improving social development, strengthening social cohesion and unity, promoting peace, ensuring social justice, enhancing government performance, and ensuring respect of human rights.', 34),('03f050b0-6fd2-42d9-8ecf-5e55b8899b84'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'In the ''Challenges for good governance'' section of the excerpt, how many major challenges are explicitly discussed by name?', '2', 'Within the excerpt the challenges explicitly discussed by name are Poverty and Corruption, giving two major challenges in the presented text.', 35),('23e3431e-3602-4604-86e1-f3813bc1cace'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'How many forms of corruption are listed under ''Definition and forms of corruption'' in the excerpt?', '5', 'The excerpt lists five forms of corruption: bribery, embezzlement, fraud, nepotism and extortion.', 36),('95c7f2d1-ff28-481b-8564-c8d2d8cd1084'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'How many top-level ways of fighting corruption are discussed in the excerpt (for example: creating awareness, citizen participation, strengthening civil service, simplifications, media, judicial strengthening)?', '6', 'The excerpt discusses six top-level mechanisms: creating public awareness, citizen participation, strengthening the civil service, simplifications of administrative procedures, media, and strengthening the judicial system.', 37),('1d5786ca-2f60-45a1-8c01-98ba256794a9'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'In the Case Study, how many specific actions of Mr. Alemu are described (for example: giving information, publicizing vacancies, timely services, punctuality and accessibility, impartial treatment, inviting participation)?', '6', 'The case study lists six specific actions by Mr. Alemu: giving information, publicizing vacancies and budget, timely services, punctuality and accessibility, impartial treatment, and inviting dwellers to participate.', 38),('b4fd3103-57e7-4b5b-81d5-4aa1e452d0a1'::uuid, '27ee5c98-d542-4d86-8cd7-6b7ee505258d'::uuid, 'fill_blank', 'How many impacts of lack of good governance are listed in the ''Impacts of lack of good governance'' section of the excerpt?', '7', 'The excerpt lists seven impacts: political instability, inability of rule of law, inability to secure justice, lack of transparency, lack of empowerment, inefficient service delivery, and administrative irregularities.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('4c257c58-1707-4183-8f60-0932ed41bfed'::uuid, '754862a7-9f9a-49b3-8c95-dd55bd166603'::uuid, 'Plagiarism', TRUE, 0),('8fb345d3-88eb-45f9-8ea8-0f27899267f5'::uuid, '754862a7-9f9a-49b3-8c95-dd55bd166603'::uuid, 'Privacy', FALSE, 1),('592e3738-7048-433c-85bc-1636d749a452'::uuid, '754862a7-9f9a-49b3-8c95-dd55bd166603'::uuid, 'Cheating', FALSE, 2),('c5e5d874-32cb-42d9-8902-7cff262d2f2c'::uuid, '754862a7-9f9a-49b3-8c95-dd55bd166603'::uuid, 'Bullying', FALSE, 3),('2af9e18a-4af5-4720-81b2-981e56bbc2c6'::uuid, '96d6d067-7e3c-4430-8bd5-2e1f6f214b96'::uuid, 'To facilitate conditions to be socially isolated', TRUE, 0),('94c70c75-1544-4b31-859d-f4bf44593a93'::uuid, '96d6d067-7e3c-4430-8bd5-2e1f6f214b96'::uuid, 'To access information about what is going on in one’s country and around the world', FALSE, 1),('1c0386fb-b203-42b1-8128-733f1cdc13d0'::uuid, '96d6d067-7e3c-4430-8bd5-2e1f6f214b96'::uuid, 'To develop creative and innovative skill', FALSE, 2),('799bec55-083e-491f-8206-d2f623c245af'::uuid, '96d6d067-7e3c-4430-8bd5-2e1f6f214b96'::uuid, 'Enable young citizens to engage in collaborative activities', FALSE, 3),('6eb77924-d07f-4c34-84a5-ed6d2c1b29a4'::uuid, '31f8b479-b112-4d5c-828c-913dbb004ffb'::uuid, 'Digital competence', TRUE, 0),('741fc436-ef42-4e4e-8b64-99430be7760d'::uuid, '31f8b479-b112-4d5c-828c-913dbb004ffb'::uuid, 'Digital citizen', FALSE, 1),('5100a73e-5a2f-4721-83ed-a972817b3036'::uuid, '31f8b479-b112-4d5c-828c-913dbb004ffb'::uuid, 'Digital piracy', FALSE, 2),('0bb36a27-f123-4840-802b-6a63453bd60b'::uuid, '31f8b479-b112-4d5c-828c-913dbb004ffb'::uuid, 'Digital bullying', FALSE, 3),('486ac118-34b7-4462-8373-c03096d6f2cb'::uuid, '71c0d6c0-fc7c-4f7a-8b89-0608c63241bc'::uuid, 'Secondhand living', TRUE, 0),('27d31296-d629-48a7-8531-e61a97fff2f1'::uuid, '71c0d6c0-fc7c-4f7a-8b89-0608c63241bc'::uuid, 'Social alienation', FALSE, 1),('603a7ebf-25ef-436f-8882-b69d07f7e02c'::uuid, '71c0d6c0-